import{i as S,r as p,j as t,L as d}from"./react-vendor-CZBNkCpJ.js";import{P as R}from"./PublicLayout-CIwRya5N.js";import{c as C}from"./index-B5eFpvA3.js";import{F as D,q as I}from"./ui-vendor-DTRzTiII.js";import{d as i}from"./versions-D6FrCFdx.js";import{C as e,L as n,a as x,f as k}from"./Footer-Z_TVqMIo.js";import"./maplibre-CnMRh2yb.js";import"./export-tools-DEuGvHId.js";import"./firebase-DYp9ZZtL.js";import"./socket-D1aRZ6Ki.js";import"./button-CeVvynAe.js";function q({document:a}){var w;const h=S(),m=p.useRef(null),[y,A]=p.useState(((w=a.sections[0])==null?void 0:w.id)??""),c=p.useCallback(()=>{var P;const o=m.current;if(!o)return;const s=a.sections.map(f=>o.querySelector(`#${f.id}`)).filter(Boolean);let l=((P=s[0])==null?void 0:P.id)??"";for(const f of s)f.getBoundingClientRect().top<=120&&(l=f.id);l&&A(l)},[a.sections]);p.useEffect(()=>{const o=m.current;if(o)return c(),o.addEventListener("scroll",c,{passive:!0}),window.addEventListener("scroll",c,{passive:!0}),window.addEventListener("resize",c),()=>{o.removeEventListener("scroll",c),window.removeEventListener("scroll",c),window.removeEventListener("resize",c)}},[c]),p.useEffect(()=>{var o;if(h.hash){const s=(o=m.current)==null?void 0:o.querySelector(h.hash);s==null||s.scrollIntoView({behavior:"smooth",block:"start"})}},[h.hash]);const b=o=>{var l;const s=(l=m.current)==null?void 0:l.querySelector(`#${o}`);s==null||s.scrollIntoView({behavior:"smooth",block:"start"})};return t.jsxs("div",{className:"container max-w-6xl py-8 md:py-12",children:[t.jsxs("header",{className:"mb-8 border-b border-border pb-8 md:mb-10",children:[t.jsxs("div",{className:"mb-4 inline-flex items-center gap-2 rounded-full border border-border bg-muted/50 px-3 py-1 text-xs font-medium text-muted-foreground",children:[t.jsx(D,{className:"h-3.5 w-3.5","aria-hidden":!0}),"Version ",a.version]}),t.jsx("h1",{className:"text-3xl font-semibold tracking-tight text-foreground md:text-4xl lg:text-5xl",children:a.title}),t.jsx("p",{className:"mt-3 max-w-3xl text-base text-muted-foreground md:text-lg",children:a.subtitle}),t.jsxs("p",{className:"mt-4 text-sm text-muted-foreground",children:["Effective date: ",t.jsx("span",{className:"font-medium text-foreground",children:a.effectiveDate})]})]}),t.jsxs("div",{className:"grid gap-8 lg:grid-cols-[240px_minmax(0,1fr)] xl:grid-cols-[260px_minmax(0,1fr)]",children:[t.jsxs("aside",{className:"lg:sticky lg:top-24 lg:self-start",children:[t.jsxs("div",{className:"rounded-xl border border-border bg-card p-4 shadow-sm",children:[t.jsx("p",{className:"mb-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground",children:"On this page"}),t.jsx("nav",{className:"space-y-1","aria-label":"Table of contents",children:a.sections.map(o=>t.jsxs("button",{type:"button",onClick:()=>b(o.id),className:C("flex w-full items-start gap-2 rounded-md px-2 py-2 text-left text-sm transition-colors",y===o.id?"bg-primary/10 font-medium text-primary":"text-muted-foreground hover:bg-muted hover:text-foreground"),children:[t.jsx(I,{className:C("mt-0.5 h-3.5 w-3.5 shrink-0 transition-opacity",y===o.id?"opacity-100":"opacity-0"),"aria-hidden":!0}),t.jsx("span",{children:o.title})]},o.id))})]}),t.jsxs("div",{className:"mt-4 lg:hidden",children:[t.jsx("label",{htmlFor:"legal-section-select",className:"sr-only",children:"Jump to section"}),t.jsx("select",{id:"legal-section-select",className:"w-full rounded-md border border-input bg-background px-3 py-2 text-sm",value:y,onChange:o=>b(o.target.value),children:a.sections.map(o=>t.jsx("option",{value:o.id,children:o.title},o.id))})]})]}),t.jsxs("div",{ref:m,className:"legal-content-scroll max-h-none overflow-visible rounded-xl border border-border bg-card p-6 shadow-sm md:p-8 lg:max-h-[calc(100vh-8rem)] lg:overflow-y-auto scroll-smooth",children:[t.jsx("article",{className:"legal-prose mx-auto max-w-3xl",children:a.sections.map(o=>t.jsxs("section",{id:o.id,className:"legal-section scroll-mt-24",children:[t.jsx("h2",{className:"legal-section-title",children:o.title}),t.jsx("div",{className:"space-y-4",children:o.content.map((s,l)=>t.jsx("p",{className:"legal-paragraph",children:s},l))})]},o.id))}),t.jsx("footer",{className:"mt-12 border-t border-border pt-6",children:t.jsxs("div",{className:"flex flex-wrap gap-3 text-sm",children:[t.jsx(d,{to:"/legal",className:"text-primary hover:underline",children:"All Policies"}),t.jsx(d,{to:"/terms",className:"text-primary hover:underline",children:"Terms"}),t.jsx(d,{to:"/privacy",className:"text-primary hover:underline",children:"Privacy"}),t.jsx(d,{to:"/escrow-policy",className:"text-primary hover:underline",children:"Payment Schedule"}),t.jsx(d,{to:"/dispute-resolution",className:"text-primary hover:underline",children:"Disputes"}),t.jsx(d,{to:"/provider-agreement",className:"text-primary hover:underline",children:"Provider Agreement"}),t.jsx(d,{to:"/refund-policy",className:"text-primary hover:underline",children:"Refunds & Returns"}),t.jsx(d,{to:"/delivery-policy",className:"text-primary hover:underline",children:"Delivery & Collection"})]})})]})]})]})}const j="August 18, 2026",N={id:"terms",title:"Terms of Service",subtitle:"The rules and guidelines for using the EloFix marketplace in South Africa.",effectiveDate:j,version:i.terms,sections:[{id:"introduction",title:"1. Introduction",content:[`Welcome to EloFix, a marketplace platform and trading brand operated by ${e.legalName} ("LITI", "we", "us", or "our"). These Terms of Service ("Terms") govern your access to and use of the EloFix platform, including our website, mobile experiences, and related services (collectively, the "Platform").`,n,"By creating an account, checking an acceptance box, or using the Platform, you agree to these Terms and to the policies incorporated by reference in Section 2. If you do not agree, you may not use EloFix.","These Terms are subject to the Electronic Communications and Transactions Act 25 of 2002 (ECTA). Your electronic acceptance constitutes a binding agreement."]},{id:"incorporated-policies",title:"2. Incorporated Policies",content:["The following policies form part of your agreement with EloFix and are available on the Platform:","Privacy Policy, Data Processing Policy, Cookie Policy, Device Security Policy, and Platform Activity Records Policy.","Refund, Returns & Cancellation Policy, Delivery & Collection Policy, Payment Schedule and Transparency Policy, Job Completion Verification Policy, Dispute Resolution Policy, and Corrective Work Policy.","Provider Agreement, Provider Verification Policy, Provider Reputation Policy, and Portfolio Content Rights (for Providers).","Supplier Agreement and Supplier Participation Policy (for Suppliers).","Community Standards, Fraud Prevention Policy, and Admin Review and Investigation Policy.","In the event of conflict between these Terms and a role-specific agreement, the role-specific agreement prevails for that role."]},{id:"definitions",title:"3. Definitions",content:['"Customer" means a user who requests maintenance, repair, delivery, or related services through the Platform.','"Provider" means an independent professional or business that offers services through the Platform.','"Supplier" means a business that lists and fulfils materials or products through the EloFix supplier marketplace.','"Branch User" means staff authorised to act on behalf of a Supplier branch.','"Job" means a service engagement arranged between a Customer and a Provider through EloFix.','"Materials" means products ordered through participating EloFix Suppliers in connection with a Job or store checkout.','"Payment Schedule" means the applicable labor payment mode for a Job (TWO_PAYMENT_50_50, SINGLE_PAYMENT_UPFRONT, or SINGLE_PAYMENT_ON_COMPLETION) or the payment model for an order, including payment milestones and status, as described in the Payment Schedule and Transparency Policy. EloFix records applicable commissions and recipient shares; actual bank settlement depends on the applicable payment service provider and settlement configuration. Customer payment timing is not the same as provider settlement timing.','"Dispute" means a formal disagreement raised through the Platform regarding Job completion or payment.',`"Trust Score" means EloFix's internal reputation metric for Providers as described in the Provider Reputation Policy.`,'"Admin" means an authorised EloFix administrator.']},{id:"eligibility",title:"4. Eligibility",content:["You must be at least 18 years old and capable of entering into a binding contract under South African law to use EloFix.","Providers must complete identity verification, submit required documents, and receive approval before accepting paid Jobs, as described in the Provider Verification Policy.","Suppliers must accept the Supplier Agreement and Supplier Participation Policy before operating on the Platform.","You are responsible for ensuring that your use of the Platform complies with applicable laws in the Republic of South Africa."]},{id:"platform-role",title:"5. EloFix as a Marketplace Facilitator",content:["EloFix is a technology marketplace that connects Customers with independent Providers and Suppliers. EloFix is not the employer of Providers, is not a supplier of goods, and does not perform the services listed on the Platform.","Providers are solely responsible for the quality, safety, legality, licensing, and delivery of their services. Customers contract directly with Providers for service work.","Suppliers are solely responsible for the accuracy, quality, legality, and delivery of products they list and fulfil.","EloFix may facilitate payments through third-party payment service providers, record transaction and commission information, support communications, scheduling, verification, fraud prevention, and dispute processes, but does not guarantee outcomes of any Job, order, or Dispute."]},{id:"accounts",title:"6. Accounts and Security",content:["You must provide accurate registration information and keep your account credentials secure.",`You are responsible for all activity under your account. Notify us immediately of unauthorized access at ${e.email}.`,"We may suspend, restrict, or terminate accounts that violate these Terms, incorporated policies, applicable law, or Platform integrity requirements, including findings under the Fraud Prevention Policy."]},{id:"payments",title:"7. Payments and Fees",content:["Customers authorize EloFix and its applicable third-party payment service providers to process charges for Jobs, materials, delivery, and applicable platform fees.","The current contractual EloFix platform commission is 7% on collected labor and materials transactions as further described in the Payment Schedule and Transparency Policy.","Provider and Supplier shares are recorded according to the Platform payment model. Where supported by EloFix's payment service provider and applicable settlement configuration, eligible funds may be settled to a nominated verified bank account. Recording a share is not the same as depositing cash into a bank account.","If an outstanding customer service balance becomes payable, it is due within 30 calendar days. Failure to settle an outstanding amount within 30 calendar days may result in restrictions on new marketplace transactions, account suspension or blocking, referral for lawful debt recovery, and further legal action where appropriate. Login remains available so the Customer can pay the outstanding amount and contact EloFix.","EloFix does not operate an account-credit, store-credit, wallet-credit, or EloFix-credit product.","All prices, fees, and taxes are displayed or communicated before payment confirmation where required by the Consumer Protection Act 68 of 2008 (CPA) and ECTA."]},{id:"conduct",title:"8. Acceptable Use",content:["You must comply with the Community Standards at all times.","You may not use the Platform for unlawful, fraudulent, abusive, or discriminatory activity.","You may not circumvent Platform payments, solicit off-platform transactions in violation of Provider or Supplier policies, or interfere with Platform operations.","We may remove content, restrict features, or report activity to authorities when necessary to protect users and the Platform."]},{id:"intellectual-property",title:"9. Intellectual Property",content:["EloFix owns the Platform, branding, software, and related intellectual property except for user-provided content.","You retain ownership of content you submit, but grant EloFix the licences described in the Portfolio Content Rights and applicable role agreements to host, display, and use that content to operate the Platform."]},{id:"indemnification",title:"10. Indemnification",content:[`You agree to indemnify, defend, and hold harmless ${e.legalName} (operating the EloFix Platform), its directors, officers, employees, and agents from claims, losses, damages, liabilities, and expenses (including reasonable legal fees) arising from your use of the Platform, your breach of these Terms or incorporated policies, or your violation of law or third-party rights.`,`Providers and Suppliers additionally indemnify ${e.legalName} for claims arising from services performed or products supplied by them, including personal injury, property damage, defective work, and regulatory non-compliance.`]},{id:"disclaimers",title:"11. Disclaimers",content:['The Platform is provided on an "as is" and "as available" basis to the fullest extent permitted by South African law.',"EloFix disclaims warranties of merchantability, fitness for a particular purpose, and non-infringement unless otherwise required by law.","Nothing in these Terms excludes liability that cannot be excluded under the CPA, ECTA, or other mandatory law."]},{id:"liability",title:"12. Limitation of Liability",content:["To the maximum extent permitted by law, EloFix is not liable for indirect, incidental, special, consequential, or punitive damages arising from your use of the Platform.","EloFix's aggregate liability for claims relating to the Platform will not exceed the greater of (a) amounts paid by you to EloFix as platform fees in the twelve months before the claim, or (b) R1,500 (one thousand five hundred South African Rand), except where prohibited by law.","EloFix is not a bank, deposit-taker, escrow agent, or insurer. Customer payments are processed by third-party payment service providers. EloFix's payment recording, commission accounting, and settlement rules are described in the Payment Schedule and Transparency Policy."]},{id:"force-majeure",title:"13. Force Majeure",content:["EloFix is not liable for failure or delay in performance caused by events beyond our reasonable control, including natural disasters, load shedding, internet or payment gateway outages, labour disputes, government action, or civil unrest."]},{id:"governing-law",title:"14. Governing Law and Jurisdiction",content:["These Terms are governed by the laws of the Republic of South Africa.","Subject to mandatory consumer protections and small claims court jurisdiction, you consent to the exclusive jurisdiction of the courts of South Africa for disputes arising from these Terms."]},{id:"assignment",title:"15. Assignment",content:["You may not assign your rights under these Terms without EloFix's prior written consent.","EloFix may assign these Terms in connection with a merger, acquisition, financing, or sale of assets, subject to appropriate notice where required by law."]},{id:"changes",title:"16. Changes to These Terms",content:["We may update these Terms from time to time. When we make material changes, we will update the effective date and version and may require renewed acceptance before new marketplace transactions. You may still log in, view existing Jobs and disputes, settle outstanding payments, and access legal and contact pages.","Your electronic acceptance of the updated documents is recorded. Previous acceptance records are retained."]},{id:"contact",title:"17. Contact",content:[`Questions about these Terms may be sent to ${e.email}.`,`Legal entity: ${e.legalName}. ${e.operatorStatement} Company registration number: ${x()}. Registered / physical business address: ${k()}. Country of domicile: ${e.country}.`]}]},J="August 18, 2026",O={id:"privacy",title:"Privacy Policy",subtitle:`How ${e.legalName}, operating the EloFix Platform, collects, uses, and protects your personal information under POPIA.`,effectiveDate:J,version:i.privacy,sections:[{id:"overview",title:"1. Overview",content:[`This Privacy Policy explains how ${e.legalName} ("LITI", "we", "us"), operating the EloFix Platform ("EloFix"), processes personal information when you use our Platform.`,n,`${e.legalName} is the responsible party under the Protection of Personal Information Act 4 of 2013 (POPIA). Our Information Officer can be contacted at ${e.email}.`,`Registered / physical business address: ${k()}. Company registration number: ${x()}. Country of domicile: ${e.country}.`,"We design our data practices to support secure marketplace operations, payment processing, fraud prevention, customer support, and legal compliance."]},{id:"lawful-basis",title:"2. Lawful Basis for Processing (POPIA Section 11)",content:["Contractual necessity: account creation, Job fulfilment, payments, payment-schedule tracking, and communications between Customers, Providers, and Suppliers.","Legal obligation: tax, financial record-keeping, regulatory requests, and dispute records.","Legitimate interest: fraud prevention, platform security, device intelligence, trust scoring, analytics, and service improvement — balanced against your rights.","Consent: marketing communications, non-essential cookies, and optional features where we request explicit consent.","Special personal information (Section 26): Provider identity documents and banking details are processed based on contractual necessity and legitimate interest for verification and payout integrity."]},{id:"information-we-collect",title:"3. Information We Collect",content:["Account information: name, email address, phone number, profile photo, role, and authentication credentials.","Provider verification data: South African ID number, business registration, proof of address, certifications, banking information, and uploaded document files.","Supplier data: business details, branch information, inventory, pricing, staff accounts, and order fulfilment records.","Transaction data: Jobs, quotations, material orders, payment intents, invoices, payment schedule and payment status, refunds, commissions, recipient shares, and delivery tracking.","Payment-related data processed by EloFix may include transaction identifiers, amounts, payment status, refund status, and ledger/accounting records. Card numbers, CVV, and full payment-instrument details are processed by the applicable third-party payment service provider according to that provider's systems; EloFix does not store CVV and does not claim to store full card numbers.","Banking details provided for provider or supplier settlement destinations (which may remain pending verification until settlement is supported).","Dispute and evidence data: comments, images, videos, messages, and admin resolution records.","Device and security data: device fingerprints, browser fingerprints, IP addresses, user agents, session activity, and login records (see Device Security Policy).","Fraud and trust data: duplicate identity signals, fraud alerts, trust score history, and investigation notes.","Communications: in-platform messages, notifications, support requests, reviews, and ratings.","Audit records: admin actions, payment events, verification decisions, and system logs (see Platform Activity Records Policy)."]},{id:"how-we-use",title:"4. How We Use Information",content:["To create and manage accounts, authenticate users, and provide Platform features.","To match Customers with Providers, process payments through payment service providers, record commissions and payment status, deliver notifications, and support Jobs and material orders.","To verify Provider identity, prevent fraud, enforce policies, calculate trust scores, and maintain marketplace safety.","To investigate disputes, process refunds, and support admin review decisions.","To improve the Platform, analyze performance, and develop new features.","To comply with legal obligations under POPIA, ECTA, CPA, and other applicable South African law."]},{id:"sharing",title:"5. How We Share Information",content:["With other users when necessary to complete a Job or order, such as sharing contact or location details relevant to service or delivery.","With third-party payment service providers, hosting providers, identity verification tools, device intelligence services (including FingerprintJS), analytics tools, and other subprocessors under contractual safeguards (see Data Processing Policy). Payment card and certain payment-instrument data may be processed directly by the payment service provider.","With regulators, law enforcement, or other parties when required by law or to protect rights, safety, and Platform integrity.","In connection with a merger, acquisition, financing, or sale of assets, subject to appropriate confidentiality protections.","We do not sell personal information."]},{id:"retention",title:"6. Data Retention",content:["We retain personal information for as long as needed to provide the Platform, satisfy legal obligations, resolve disputes, and enforce agreements.","Indicative retention periods: active account data for the duration of the account plus 5 years; KYC/verification documents for 5 years after relationship ends; payment and commission records for 7 years; audit logs for 5 years; device session records for 24 months; dispute records for 5 years after resolution; fraud investigation records for 5 years.","Retention periods may vary based on document type, account status, and regulatory requirements. We delete or anonymize data when retention is no longer justified."]},{id:"security",title:"7. Security",content:["We use administrative, technical, and organizational measures designed to protect personal information, including encryption of sensitive fields, access controls, and audit logging.",`No method of transmission or storage is completely secure. You should protect your account credentials and report suspicious activity promptly to ${e.email}.`]},{id:"your-rights",title:"8. Your Rights and Choices (POPIA)",content:["You have the right to request access to, correction of, deletion of, or restriction on processing of your personal information, subject to legal exceptions.","You may object to processing based on legitimate interest where applicable.","You may update certain account details in your profile settings and manage marketing preferences where offered.",`To exercise privacy rights, contact ${e.email}. We will respond within 30 days, subject to identity verification.`,"You have the right to lodge a complaint with the Information Regulator of South Africa if you believe your rights have been violated.",`Access to records may also be requested under the Promotion of Access to Information Act 2 of 2000 (PAIA) by contacting ${e.email}.`]},{id:"ecta-cpa",title:"9. ECTA and Consumer Protection",content:["Under ECTA, your electronic acceptance of Platform terms constitutes valid consent to electronic transactions and communications.","Under the CPA, you have rights regarding fair and honest dealing, disclosure of prices, and remedy for defective goods or services. Nothing in this Policy limits mandatory consumer rights.","Refund and cancellation rights are further described in the Refund, Returns & Cancellation Policy."]},{id:"cookies",title:"10. Cookies and Similar Technologies",content:["We use cookies and similar technologies for authentication, preferences, analytics, and security. See our standalone Cookie Policy for details."]},{id:"international",title:"11. International Transfers",content:["Your information may be processed in countries other than South Africa, including where our hosting or subprocessors operate.","Where required, we implement appropriate safeguards for cross-border transfers consistent with POPIA requirements."]},{id:"children",title:"12. Children",content:["EloFix is not directed to children under 18, and we do not knowingly collect personal information from children."]},{id:"updates",title:"13. Policy Updates",content:["We may revise this Privacy Policy from time to time. Material changes will be reflected in the updated effective date and version, and we may request renewed consent where required."]},{id:"contact",title:"14. Contact Us",content:[`Privacy questions or data subject requests: ${e.email} (Information Officer).`,`General / legal contact: ${e.email}.`]}]},E="August 18, 2026",W={id:"provider-agreement",title:"Provider Agreement",subtitle:"Additional terms for professionals offering services on EloFix.",effectiveDate:E,version:i.providerAgreement,sections:[{id:"relationship",title:"1. Independent Provider Relationship",content:[n,"This Provider Agreement supplements the EloFix Terms of Service for users who register as Providers.",`You acknowledge that you are an independent contractor and not an employee, agent, joint venturer, or partner of ${e.legalName}.`,"You control how you perform services, subject to Customer requirements, applicable South African law, and Platform standards.","You are responsible for your own tax, UIF, COIDA, and statutory obligations as an independent service provider."]},{id:"onboarding",title:"2. Onboarding and Verification",content:["You must complete profile setup, submit required verification documents, and receive approval before accepting paid Jobs, as described in the Provider Verification Policy.","Required documents may include South African ID, business registration, proof of address, banking information for a settlement destination profile, and optional certifications.","Saving banking details does not mean settlement is enabled, that a payout destination is verified with a payment service provider, or that EloFix may debit your bank account.","EloFix may reject, suspend, revoke verification, or request updated documentation at any time based on verification results, fraud review status, or policy violations.","You represent that all submitted information and documents are accurate, current, and belong to you or your business."]},{id:"service-standards",title:"3. Service Standards",content:["You agree to perform services professionally, safely, and in compliance with applicable licenses, permits, and trade regulations in South Africa.","You will communicate clearly with Customers, honor agreed schedules where possible, and use the Platform for Job-related updates and payment flows.","You are responsible for your tools, labor, subcontractors, insurance, and tax obligations.","If instructed to return for corrective work under the Corrective Work Policy, you must complete remedial work and re-submit the Job for Customer verification."]},{id:"pricing",title:"4. Pricing, Quotes, and Changes",content:["You may set labor pricing and propose quotes according to Platform workflows.","Material recommendations and orders must follow EloFix ordering rules when Platform fulfilment is used.","Any scope changes should be documented and approved through Platform flows before additional charges are incurred where applicable."]},{id:"payments-payouts",title:"5. Payments and Settlement",content:["Customer labor payments are processed through EloFix's applicable third-party payment service providers. EloFix records the current contractual platform commission of 7% of each collected customer labor payment tranche and your provider share (93% of that collected tranche) according to the Payment Schedule and Transparency Policy.","Recording your share in EloFix's ledger is not the same as depositing cash into your bank account. Customer payment timing is not the same as provider settlement timing. Where supported by EloFix's payment service provider and applicable settlement configuration, eligible provider funds may be settled to your nominated verified bank account.","The Platform supports three live labor payment modes, as shown on the Job:","TWO_PAYMENT_50_50 — the Customer pays an approximately 50% first tranche, then a remaining completion tranche according to the Job workflow. Commission of 7% applies to each collected customer payment tranche.","SINGLE_PAYMENT_UPFRONT — the Customer pays the full service amount before work progresses.","SINGLE_PAYMENT_ON_COMPLETION — the Customer does not pay labor upfront. Payment becomes due after the configured completion or confirmation flow.","Not all Jobs use escrow. EloFix does not hold all provider shares as deposits.","Settlement timing and eligibility may be delayed or paused for fraud review, open disputes, chargebacks, policy violations, incomplete verification, overdue refund repayment, or legal compliance, subject to payment-service-provider capabilities.","You authorize EloFix to deduct applicable platform fees, refunds, clawbacks, adjustments, and chargebacks from amounts otherwise recorded as payable to you.","If a Customer refund requires recovery from you after amounts attributable to you have already been accounted for or paid out, you must complete provider repayment within 30 calendar days through the supported mechanisms (gateway repayment checkout where available, and/or bank transfer / EFT using the reference EloFix provides). Failure to settle an approved refund repayment or other recoverable amount within 30 calendar days may result in restrictions on new work, settlement restrictions, account blocking, referral for lawful debt recovery, and further legal action where appropriate. You may still log in, view Jobs and earnings, access the repayment page, submit repayment, and contact EloFix. Entering banking details does not authorize EloFix to debit your bank account automatically unless a payment service provider expressly supports that capability and you are notified of such terms."]},{id:"job-completion",title:"6. Job Completion and Customer Verification",content:["When you mark a Job as complete, the Customer receives notification and has 7 calendar days to accept or dispute the work under the Job Completion Verification Policy.","If the Customer does not respond within 7 days, the Job may be automatically approved and any remaining payment tranche for a staged-payment Job may become payable according to the Payment Schedule and Transparency Policy.","Open disputes block automatic acceptance and may pause settlement of any remaining staged payment tranche until resolved."]},{id:"materials-delivery",title:"7. Materials and Delivery",content:["When you recommend or fulfil materials, you must ensure accuracy of specifications and comply with supplier and delivery policies, including the Delivery & Collection Policy.","Delivery ratings and fulfilment performance may affect your visibility, eligibility, and aggregate rating on the Platform."]},{id:"reviews-reputation",title:"8. Reviews, Reputation, and Trust Score",content:["Customers may rate and review your services. EloFix may display aggregated ratings, completed Job metrics, and portfolio content on your profile.","Your Trust Score is calculated under the Provider Reputation Policy based on verification, reviews, completion rate, disputes, refunds, and fraud signals. Trust scores may affect your visibility and ranking.","You may not manipulate reviews, retaliate against Customers for honest feedback, or request removal of legitimate reviews except through Platform support processes."]},{id:"fraud-compliance",title:"9. Fraud Prevention and Compliance",content:["You agree to comply with the Fraud Prevention Policy and Device Security Policy.","Duplicate identities, suspicious devices, or fraudulent documentation may result in suspension, verification revocation, or permanent removal.","Provider approval may be blocked while fraud review status is PENDING_REVIEW or REJECTED."]},{id:"insurance",title:"10. Insurance and Liability",content:["You are solely responsible for injuries, property damage, or losses arising from your services unless otherwise required by law.","EloFix recommends maintaining appropriate public liability, professional indemnity, and workers compensation coverage where applicable.","You indemnify EloFix for claims arising from your services, as described in the Terms of Service."]},{id:"termination",title:"11. Suspension and Termination",content:["EloFix may suspend or remove Provider access for policy violations, safety concerns, poor performance, fraud, or legal risk.","You may deactivate your account subject to completion of outstanding Jobs, payment obligations, and dispute resolution requirements."]},{id:"updates",title:"12. Updates",content:["We may update this Provider Agreement from time to time. Material changes may require renewed acceptance before you continue accepting new Jobs."]}]},$={id:"refund-policy",title:"Refund, Returns & Cancellation Policy",subtitle:"How cancellations, refunds, returns, and adjustments work for EloFix services and material orders.",effectiveDate:E,version:i.refundPolicy,sections:[{id:"overview",title:"1. Overview",content:[n,`This policy describes how cancellations, refunds, returns, and adjustments are handled for service Jobs and material orders arranged through the EloFix Platform operated by ${e.legalName}.`,"This policy distinguishes service transactions (labor Jobs with independent Providers) from material orders (goods from independent Suppliers).","Specific refund eligibility depends on Job or order status, which payment amounts the Customer has actually paid, Provider acceptance, supplier fulfilment stage, payment-schedule status, and applicable South African law including the Consumer Protection Act.","An unpaid payment tranche is not treated as money already paid by the Customer. Refunds are based on eligible paid amounts, not the full original quotation where only a deposit or partial amount was paid.","For payment schedules and settlement rules, see the Payment Schedule and Transparency Policy. For completion disputes, see the Dispute Resolution Policy. For collection and delivery modes, see the Delivery & Collection Policy."]},{id:"service-before-work",title:"2. Service Transactions — Cancellation Before Work",content:["Customers may cancel a Job before a Provider begins work subject to any displayed cancellation terms at checkout or quote acceptance.","If labor has not been paid, cancellation typically results in no labor charge.","If labor has been paid and amounts attributable to the Provider have not yet been treated as payable or settled under the applicable payment schedule, the Customer may receive a labor refund calculated on the eligible paid amount, net of the platform commission (93% of gross labor paid). The 7% platform fee is not refunded.","If a mobilisation or other provider tranche has already become payable or been accounted for under the payment schedule, cancellation refunds are limited to remaining eligible unpaid or recoverable amounts — not necessarily the full original quotation or total paid amount."]},{id:"service-after-work",title:"3. Service Transactions — Cancellation After Work Starts",content:["Once work has started on a standard service Job, a Customer cancellation of paid work does not automatically forfeit the paid amount and does not automatically produce a R0 refund.","If labor has been paid and the Customer cancels after work has started, EloFix may open an administrator review or cancellation dispute. A refund is not guaranteed. An administrator determines the outcome according to the circumstances, the Job records, and eligible paid amounts.","Unpaid payment tranches are not automatically charged merely because a cancellation or review was opened. Only eligible paid amounts can be considered for refund.","Administrators may resolve a cancellation review using the existing dispute outcomes described in the Dispute Resolution Policy (including refund, partial refund, release of remaining payment, return for corrective work, or case closure).","Courier and moving Jobs follow separate hard cancellation rules in Section 3A and in the Delivery & Collection Policy. Those courier rules are not the same as ordinary service cancellation."]},{id:"paid-unpaid-tranches",title:"4. Service Transactions — Paid vs Unpaid Payment Tranches",content:["EloFix does not treat an unpaid payment tranche as money already paid by the Customer.","For staged-payment Jobs, a mobilisation tranche and a completion tranche may apply as shown at checkout and in the Job details. Only amounts the Customer has actually paid are eligible for refund consideration.","Unpaid remaining tranches are not refunded because they have not been collected. They may simply not become payable if the Job is cancelled or resolved without that tranche becoming due.","Refund calculations on paid labor follow the Payment Schedule and Transparency Policy and the processing rules in this policy."]},{id:"courier-cancellation",title:"4A. Courier and Moving Jobs — Cancellation Restrictions",content:["Courier and moving Jobs have separate cancellation rules from ordinary service Jobs.","A Customer generally cannot cancel a courier or moving Job after items have been collected (picked up), or while the Job is awaiting completion confirmation.","While a courier Provider is collecting items and labor has been paid, Customer cancellation may result in no labor refund (R0) under the en-route forfeiture rule implemented on the Platform.","These courier restrictions remain even where ordinary service cancellation would instead open an administrator review.","Material-order refunds, if any, remain subject to the material-order rules in this policy and the Delivery & Collection Policy."]},{id:"provider-cancellations",title:"5. Provider Cancellations",content:["Providers should avoid cancellations after acceptance. Repeated cancellations may affect account standing, trust score, visibility, and settlement eligibility.","If a Provider cancels without valid reason, EloFix may assist the Customer with reassignment or a refund of eligible paid amounts where appropriate. EloFix does not issue account credits, store credit, wallet credit, or EloFix credit."]},{id:"incomplete-defective",title:"6. Incomplete or Defective Work",content:["If work is incomplete, defective, or not as agreed, the Customer should use the Job completion verification window and, where eligible, the Dispute Resolution Policy rather than a card chargeback as a first step.","Administrators may order a full refund, partial refund, release of remaining payment, return for corrective work, or case closure, based on Platform records and submitted evidence.","Corrective work is described in the Corrective Work Policy and does not automatically create an additional labor charge unless separately agreed through Platform flows."]},{id:"disputes",title:"7. Disputes",content:["Customers may open a completion dispute while the Job is in Awaiting Confirmation, as described in the Dispute Resolution Policy.","A cancellation request on an eligible Job may also open an administrator dispute or review from other Job statuses. Not all disputes are limited to Awaiting Confirmation.","Requesting a refund in a dispute does not automatically trigger a refund. EloFix administrators investigate and may order full refund, partial refund, release of remaining payment, return for corrective work, or case closure.","Open disputes may pause settlement of any remaining staged payment tranche until resolved.","When part of an approved refund must be recovered from a Provider, that portion is not guaranteed instantly. The Provider has 30 calendar days to complete repayment via supported gateway repayment and/or bank transfer / EFT (and/or recovery from future earnings where applicable) before account restrictions on new work may apply.","Failure to settle an approved refund repayment or other recoverable amount within 30 calendar days may result in restrictions on new work, settlement restrictions, account blocking, referral for lawful debt recovery, and further legal action where appropriate."]},{id:"material-cancellations",title:"8. Material Orders — Cancellations",content:["Material orders may be cancelled by the Customer while the order is still pending, accepted, being prepared, or ready for collection, subject to supplier policies and Platform status rules.","Customer cancellation is generally not available after the order has been dispatched or is out for delivery.","Custom, special-order, cut-to-size, delivered, or installed materials may not be refundable once fulfilment has progressed.","If a supplier cancels an order, refund treatment follows Platform accounting for that cancellation type, including commission reversals where the Platform applies them.","Material payments are processed through the applicable payment service provider. Supplier share is recorded after commission accounting and is not subject to job-completion staged payment holds. Actual bank settlement to a Supplier or branch depends on supported marketplace settlement configuration."]},{id:"material-incorrect-damaged",title:"9. Material Orders — Incorrect, Damaged, Defective, or Unavailable Goods",content:["Incorrect goods: if items received do not match the order, report the issue through the Platform after fulfilment is marked complete and before confirming receipt, using the delivery-issue process where available.","Damaged goods: report broken or damaged items through the same Platform process, with photographs or other evidence where requested.","Defective goods: quality or manufacturing defects should be reported through the Platform so the supplier can investigate. The supplier remains responsible for the goods they supply, subject to the Supplier Agreement and applicable law.","Unavailable goods: if items cannot be fulfilled because they are out of stock or otherwise unavailable, the supplier should update the order through the Platform. Cancellation or substitution then follows Platform status and any confirmation shown to the Customer.","EloFix facilitates reporting and related records. EloFix is not the seller of the goods."]},{id:"material-returns-exchanges",title:"10. Material Orders — Returns and Exchanges",content:["Returns and exchanges, where offered, are handled with the fulfilling supplier through the Platform and any instructions displayed on the order or at checkout.","EloFix does not publish a statutory cooling-off period, restocking fee, or universal return window on this page. Any return timing, condition requirements, or costs are as displayed at checkout or as confirmed with the supplier on the Platform.","Not all goods are returnable. Custom, special-order, cut, mixed, hazardous, perishable, or installed items may be excluded by the supplier or by the nature of the goods.","An exchange is not guaranteed. Where a supplier agrees to an exchange, it is an arrangement between the Customer and that supplier, recorded through the Platform where those tools exist.","Any return-shipping or collection cost is as displayed or as confirmed with the supplier. This policy does not invent a fee or a free-return promise."]},{id:"material-delivery-returns",title:"11. Material Orders — Delivery-Related Return Issues",content:["Delivery-related issues (missing items, damaged items, wrong items, goods not received, or other problems described on the Platform form) should be reported promptly after fulfilment is marked complete and before the Customer confirms receipt.","Reporting notifies the relevant supplier branch so the matter can be investigated. A delivery-issue report may block receipt confirmation until handled according to Platform processes.","Outcomes may include investigation, replacement, return, partial refund, full refund, or no adjustment, depending on evidence, fulfilment stage, and applicable law.","Collection, store delivery, and courier delivery modes are described in the Delivery & Collection Policy. This section does not change those operational rules."]},{id:"refund-process",title:"12. Refund Processing",content:["Refunds follow Platform status steps. Typical statuses include: refund approved; refund processing; refund completed; refund requires manual processing; or refund could not be completed.","Where provider repayment is required after an admin resolution, the Provider must complete repayment through a supported mechanism. After repayment is verified where required, the Customer refund may become ready for processing. An administrator then explicitly processes the Customer refund through the applicable payment service provider.","A refund is described as returned to the original payment method only after the applicable payment service provider confirms the refund. Before confirmation, EloFix will show accurate processing status, including where manual processing by the payment service provider is required.","Processing times vary by payment service provider and bank. EloFix does not promise instant or automatic refunds to a Customer's card or bank account.","Customer labor refunds are calculated on eligible paid labor amounts, net of the platform commission (93% of gross labor paid). The 7% platform fee is not refunded.","When part of an approved refund depends on recovering amounts from a Provider, that portion is not guaranteed instantly. EloFix processes the Customer refund as recovery and admin processing complete, within approximately 30 calendar days for the Provider repayment obligation where applicable.","EloFix does not operate an account-credit, store-credit, wallet-credit, or EloFix-credit product. Supported refund outcomes are a refund to the original payment method where the payment service provider confirms it, manual processing where required, provider repayment or recovery, administrator review, and failed or manual statuses.","Platform commission on labor is not refunded to Providers on labor refunds processed through admin dispute resolution."]},{id:"auto-acceptance",title:"13. Automatic Acceptance",content:["If a Customer does not accept or dispute completed work within 7 calendar days, the Job may be automatically approved under the Job Completion Verification Policy.","Automatic acceptance may make any remaining customer payment tranche payable according to the Payment Schedule and Transparency Policy. Customer payment timing is not the same as provider bank settlement timing."]},{id:"chargebacks",title:"14. Chargebacks",content:["Initiating a chargeback without first using Platform support may delay resolution and affect account access.","Providers and suppliers may be required to repay or otherwise settle chargebacks, refunds, or adjustments associated with their Jobs or orders through supported Platform repayment and accounting mechanisms. This does not mean EloFix can automatically debit a bank account unless a payment service provider expressly supports that capability."]},{id:"non-refundable",title:"15. Non-Refundable Items",content:["Completed services properly delivered and accepted (including by automatic acceptance), non-returnable materials, third-party fees already incurred, and applicable platform service fees may be non-refundable except where required by the CPA or other mandatory law."]},{id:"outstanding-payments",title:"15A. Outstanding Customer Payments",content:["If an administrator resolution or normal Job workflow makes an outstanding customer service balance payable, the Customer must settle that amount within 30 calendar days of the due date shown on the Platform.","Until the due date, the Customer may continue to use the marketplace, subject to other Platform rules.","If the amount remains unpaid after the due date, new marketplace transactions may be restricted. The Customer may still log in, view Jobs, disputes, invoices, and payment obligations, pay the outstanding amount, and contact EloFix.","Failure to settle an outstanding amount within 30 calendar days may result in restrictions on new marketplace transactions, account suspension or blocking, referral for lawful debt recovery, and further legal action where appropriate."]},{id:"changes",title:"16. Policy Changes",content:["We may update this policy from time to time. The effective date and version on this page indicate the current policy in effect."]},{id:"contact",title:"17. Contact",content:[`Refund, returns, and cancellation questions may be sent to ${e.email} with your Job or order reference number.`,`${e.operatorStatement} Country of domicile: ${e.country}.`]}]},F="August 18, 2026",Y={id:"job-completion-verification",title:"Job Completion Verification Policy",subtitle:"How Customers verify completed work and how Jobs are closed on EloFix.",effectiveDate:F,version:i.jobCompletionVerification,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the process by which Providers mark Jobs as complete and Customers verify completed work on the EloFix Platform, operated by ${e.legalName}.`,n,"It forms part of the Payment Schedule and Transparency Policy and governs when the final provider payment tranche may become payable for staged-payment Jobs."]},{id:"provider-marks-complete",title:"2. Provider Marks Job Complete",content:["When a Provider determines that service work is finished, they mark the Job as complete through the Platform.","The Job status changes to Awaiting Confirmation. The Customer receives a notification that the Provider has completed the work.","The Platform records the completion timestamp (markedCompleteAt) and sets a confirmation deadline of 7 calendar days from that moment (confirmationDeadlineAt).","The Provider receives notification that the Job is awaiting Customer confirmation."]},{id:"customer-inspection",title:"3. Customer Inspection Period",content:["The Customer has 7 calendar days from the completion timestamp to inspect the work on-site or through agreed means.","During this period, the Customer may either accept the work or open a dispute.","The Customer should review the work promptly and report any concerns before the deadline expires."]},{id:"manual-acceptance",title:"4. Manual Acceptance",content:["To manually accept completed work, the Customer must submit a star rating (1 to 5), at least one photo or video of the completed work, and may include a written review.","Upon acceptance: the Job is marked Completed, completion evidence is stored, a Provider review may be published, any remaining payment tranche for a staged-payment Job becomes payable to the Provider according to the Payment Schedule and Transparency Policy, and the transaction is closed.","Written reviews may be edited within 10 minutes of first submission.","Manual acceptance cannot occur while an open dispute exists on the Job."]},{id:"dispute-option",title:"5. Dispute Option",content:["If the Customer is not satisfied with the completed work, they may open a dispute during the 7-day verification window.","Disputes are handled under the Dispute Resolution Policy. Opening a dispute blocks automatic acceptance and may pause release of any remaining payment tranche until the dispute is resolved."]},{id:"automatic-acceptance",title:"6. Automatic Acceptance (Silence = Acceptance)",content:["If the Customer does not accept or dispute the completed work within 7 calendar days, the Job is automatically approved by the Platform.","Upon automatic acceptance: the Job is marked Completed, any remaining payment tranche for a staged-payment Job becomes payable to the Provider according to the Payment Schedule and Transparency Policy, and the transaction is closed.","The Customer acknowledges that failure to respond within the 7-day verification window constitutes acceptance of the work quality as completed by the Provider.","Automatic acceptance does not require the Customer to submit a rating, review, or media. No public star review is created. A neutral trust score adjustment may apply to the Provider.","Automatic acceptance does not occur if an open dispute exists or if completion evidence or final payment release has already been processed for the Job."]},{id:"re-completion",title:"7. Re-Completion After Corrective Work",content:["If a Provider is instructed to return for corrective work under the Corrective Work Policy, the completion verification process restarts when the Provider re-marks the Job as complete.","A new 7-day Customer verification window applies from the new completion timestamp."]},{id:"contact",title:"8. Contact",content:[`Questions about job completion verification: ${e.email}.`]}]},L={id:"escrow-policy",title:"Payment Schedule and Transparency Policy",subtitle:"How payment schedules, staging, and settlement work for Jobs and orders on EloFix.",effectiveDate:F,version:i.escrowPolicy,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes how ${e.legalName}, operating the EloFix Platform, facilitates Customer payments to Providers and Suppliers according to transparent payment schedules for each service or order type.`,n,"EloFix is a marketplace facilitator, not a bank, deposit-taker, or escrow agent. EloFix does not hold Customer funds as deposits and does not guarantee Provider or Supplier earnings.","Customer payments are processed through third-party payment service providers. EloFix records applicable transaction information, platform commissions, and recipient shares. Actual settlement to a Provider or Supplier bank account depends on the supported payment service provider and settlement configuration. Whether any arrangement is treated as escrow or another regulated payment activity under South African law depends on the licensed provider's product and requires appropriate legal advice. This document is informational platform policy only and is not legal advice or a claim of regulatory approval."]},{id:"labor-payment-schedule",title:"2. Labor Payment Schedules",content:["When a Customer pays for labor on a Job, the gross labor amount for that collected tranche is processed through the applicable payment service provider.","The current contractual EloFix platform commission is 7% of each collected customer labor payment tranche. The Provider share is 93% of that collected tranche and is recorded in EloFix's financial ledger.","Customer payment timing is not the same as provider settlement timing. A recorded or payable share is not automatically a cash deposit into the Provider's bank account.","Not all Jobs use escrow. EloFix does not hold all provider shares, and EloFix is not a deposit-taking escrow agent.","The Platform supports three live labor payment modes. The applicable mode is shown at checkout and in the Job details:","TWO_PAYMENT_50_50 — the Customer pays a first payment of approximately 50% of the service amount, then a remaining completion payment according to the Job workflow. Commission of 7% applies to each collected customer payment tranche.","SINGLE_PAYMENT_UPFRONT — the Customer pays the full service amount upfront before work progresses. Commission of 7% applies to that collected payment.","SINGLE_PAYMENT_ON_COMPLETION — the Customer does not pay labor upfront. Payment becomes due after the configured completion or confirmation flow. Commission of 7% applies when that payment is collected.","Provider workflow: receive requests → quote → receive the applicable customer payment for that category model where due → perform work → request completion → receive any remaining recorded share where applicable."]},{id:"material-payments",title:"3. Material and Supplier Payments",content:["Material order payments are subject to a 7% platform commission on the materials subtotal. The supplier earning is the subtotal minus commission and is recorded after payment confirmation.","Material payments are not subject to job-completion staged payment holds. Where supported by EloFix's payment service provider and applicable settlement configuration, eligible Supplier or branch funds may be settled to a nominated verified bank account. EloFix does not promise automatic bank settlement where marketplace settlement is not supported.","Delivery fees are processed as separate payment intents and follow their own timing with the payment service provider."]},{id:"customer-transparency",title:"4. Customer Transparency",content:["Customers see the applicable payment model (TWO_PAYMENT_50_50, SINGLE_PAYMENT_UPFRONT, or SINGLE_PAYMENT_ON_COMPLETION) before confirming payment for a Job.","For TWO_PAYMENT_50_50 Jobs, Customers may dispute completed work within the 7-day verification window, which may pause the remaining customer payment pending investigation.","If an outstanding customer service balance becomes payable, the Customer must settle it within 30 calendar days. Failure to settle an outstanding amount within 30 calendar days may result in restrictions on new marketplace transactions, account suspension or blocking, referral for lawful debt recovery, and further legal action where appropriate.","Cancellation refunds follow the Refund, Returns & Cancellation Policy. Courier en-route forfeiture, where implemented, is separate from ordinary service cancellation review."]},{id:"provider-transparency",title:"5. Provider Transparency",content:["Providers see the mobilisation tranche (where applicable) become payable upon confirmed labor payment, according to the category payment model shown on the Job.","Any remaining tranche becomes payable upon Customer acceptance, automatic acceptance, or admin resolution in the Provider's favour.","EloFix does not promise to hold, safeguard, or guarantee Provider money as deposits. Timing of any bank settlement depends on the payment service provider and Platform status rules (including open disputes).","Final staged tranches generally do not become payable for settlement while an open dispute exists, except by administrator decision."]},{id:"elofix-rights",title:"6. EloFix Rights and Commission",content:["EloFix retains the current contractual 7% platform commission on confirmed labor and material transactions.","EloFix may delay, withhold instructions for, or reverse settlement steps for fraud review, chargebacks, policy violations, open disputes, or legal compliance, subject to payment-service-provider capabilities.","Commission is not refunded to Providers on labor refunds processed through dispute resolution.","When refund recovery from a Provider is required, Customer refunds follow the Refund, Returns & Cancellation Policy: provider repayment where required, admin verification, then payment-service-provider refund processing (which may complete, require manual processing, or fail)."]},{id:"cancellation-refunds",title:"7. Cancellation and Refund Impact on Payment Schedules",content:["Before provider amounts become payable under the schedule: net labor refund to Customer (93% of eligible paid gross), subject to payment-service-provider processing and confirmation.","After a first tranche has become payable on a TWO_PAYMENT_50_50 Job: refund may be limited to any remaining unsettled balance plus recoverable provider amounts; any shortfall is recovered from the Provider over up to 30 calendar days.","Admin partial or full refunds through dispute resolution may trigger provider clawback from unsettled balances, recorded earnings, or recorded refund debt as applicable."]},{id:"disputes",title:"8. Disputes and Payment Pause",content:["When a Customer opens a dispute, the labor payment intent is marked as disputed and any remaining staged tranche does not become payable for settlement until the dispute is resolved.","Administrator outcomes may include full refund, partial refund, release of remaining payment, return for corrective work, or case closure. See the Dispute Resolution Policy."]},{id:"limitation",title:"9. Limitation of Liability",content:["EloFix is not liable for failures, delays, or errors of payment service providers, banks, or card networks.","EloFix does not guarantee that Providers or Suppliers will perform to Customer expectations, and does not guarantee that payments will settle on any particular date beyond what the payment service provider facilitates.","To the maximum extent permitted by South African law, EloFix's aggregate liability for payment-schedule-related claims is limited to the greater of platform fees paid by you in the prior 12 months or R1,500, except where prohibited by the CPA, ECTA, or other mandatory law.","Nothing in this policy limits mandatory consumer rights under South African law."]},{id:"contact",title:"10. Contact",content:[`Payment schedule questions: ${e.email}.`]}]},v="August 18, 2026",M={id:"dispute-resolution",title:"Dispute Resolution Policy",subtitle:"How EloFix handles disagreements about completed Jobs and payments.",effectiveDate:v,version:i.disputeResolution,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes how Customers and Providers resolve disagreements about completed service work on the EloFix Platform, operated by ${e.legalName}.`,n,"EloFix provides dispute facilitation and investigation. EloFix does not guarantee any particular outcome.","Disputed payment amounts are managed according to payment status and Platform accounting. EloFix does not hold disputed money as a deposit-taking escrow agent."]},{id:"eligibility",title:"2. Eligibility to Open a Dispute",content:["Only the Customer on a Job may open a dispute.","Completion dispute: the Customer may reject Provider completion while the Job is in Awaiting Confirmation during the 7-day verification window. That path uses the current completion-dispute process.","Cancellation dispute: a cancellation request may open an administrator dispute or review from other eligible Job statuses. Cancellation disputes are not limited to Awaiting Confirmation.","This policy does not claim that all disputes can only be opened during Awaiting Confirmation.","Only one active dispute (open or under investigation) may exist per Job at a time.","Customers cannot confirm completion while an open dispute exists."]},{id:"customer-submission",title:"3. Customer Dispute Submission",content:["To open a dispute, the Customer must provide a written comment describing the issue.","The Customer may upload supporting evidence including photographs, videos, and notes.","The Customer must select a requested resolution: Provider return to fix, refund (admin determines partial or full), or other (with detail).","Requesting a refund does not automatically trigger a refund. Administrator investigation and determination are required."]},{id:"provider-response",title:"4. Provider Response",content:["The Provider is notified when a dispute is opened and may submit evidence including photographs, videos, explanations, and progress reports.","The Provider may participate in the dispute message thread through the Platform.","Failure to respond may be considered in the investigation but does not automatically determine the outcome."]},{id:"investigation",title:"5. EloFix Investigation",content:["EloFix administrators review submitted evidence, Platform records, payment history, completion evidence, and communications.","Disputes may be marked as open, under investigation, resolved, or closed.","Multi-round dispute history is maintained. A resolved or closed dispute may be reopened if new issues arise, creating a new dispute round.","During investigation, any remaining staged payment tranche remains paused and the labor payment intent is marked as disputed."]},{id:"outcomes",title:"6. Possible Outcomes",content:["Release remaining payment: Any remaining staged payment tranche becomes payable to the Provider according to the Payment Schedule and Transparency Policy. The Job is marked Completed and the dispute is closed.","Partial Refund: A specified net amount based on eligible paid labor (up to 93% of gross labor paid) may be approved for the Customer. Provider clawback or repayment obligations may apply. The Job may be cancelled.","Full Refund: The maximum net labor refund based on eligible paid labor (93% of gross labor paid) may be approved for the Customer. Provider clawback or repayment obligations may apply. The Job is cancelled.","Return Provider (Corrective Work): The Provider is instructed to return and fix the work. The Job reopens to In Progress. See the Corrective Work Policy.","Close Case: The dispute is resolved without remaining-payment release or refund adjustment, based on administrator determination."]},{id:"refund-processing",title:"7. Refund Processing",content:["Approved refunds follow the Refund, Returns & Cancellation Policy sequence, including provider repayment where required, admin verification, and payment-service-provider processing.","Customer refunds are calculated on eligible paid labor (93% of gross labor paid; platform commission is retained). Provider clawback is calculated on the provider share.","Refund statuses may include approved, processing, completed, requires manual processing, or could not be completed. A refund is described as returned to the original payment method only after payment-service-provider confirmation.","When recovery from a Provider is required, that portion is not guaranteed instantly. Providers must complete repayment within 30 calendar days through supported gateway repayment and/or bank transfer / EFT (and/or recovery from future earnings where applicable).","Failure to settle an approved refund repayment or other recoverable amount within 30 calendar days may result in restrictions on new work, settlement restrictions, account blocking, referral for lawful debt recovery, and further legal action where appropriate.","Trust score adjustments may apply following dispute outcomes."]},{id:"finality",title:"8. Decision Finality",content:["Administrator dispute decisions are final on the Platform, subject to applicable South African law and consumer rights that cannot be contracted away.","See the Admin Review and Investigation Policy for administrator authority."]},{id:"contact",title:"9. Contact",content:[`Dispute support: ${e.email} with your Job reference number.`]}]},V={id:"admin-investigation",title:"Admin Review and Investigation Policy",subtitle:"How EloFix administrators review Platform activity and make decisions.",effectiveDate:v,version:i.adminInvestigation,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the authority and procedures of administrators of ${e.legalName}, operating the EloFix Platform, in reviewing Platform activity, investigating issues, and making binding Platform decisions.`,n]},{id:"admin-authority",title:"2. Administrator Authority",content:["EloFix administrators may, as necessary to operate the Platform safely and lawfully:","Review dispute evidence, completion evidence, and communications between users.","Review payment activity, payment-schedule status, customer payment obligations, refunds, provider repayment, overdue debt, and chargebacks.","Review Provider verification documents and approve or reject verification.","Review fraud alerts, device intelligence records, and duplicate identity signals.","Review audit logs and Platform activity records.","Block or unblock user accounts.","Approve or reject Provider applications and individual KYC documents.","Set Provider fraud review status.","Release remaining payment, pause settlement steps, or process refund-related actions according to Platform payment status and payment-service-provider capabilities.","Resolve disputes with outcomes including refunds, release of remaining payment, corrective work orders, or case closure.","Review settlement and banking-destination records for Providers and Suppliers. In-app withdrawal of earnings is not a current Platform product feature.","Manage Supplier accounts and material order issues."]},{id:"investigation-process",title:"3. Investigation Process",content:["Administrators act on information available through the Platform, including user-submitted evidence, system records, payment service provider data, and audit logs.","Administrators may request additional information or verification from users during an investigation.","Investigations may result in account restrictions, verification revocation, payment-status actions, refunds, or referral to law enforcement where appropriate."]},{id:"decision-finality",title:"4. Decision Finality",content:["Administrator decisions on the Platform are final unless otherwise required by applicable South African law.","Mandatory consumer rights under the Consumer Protection Act, data subject rights under POPIA, and other non-waivable legal rights are not affected by this policy.",`Users may contact ${e.email} to request review of administrator actions. EloFix is not obligated to reopen decided matters except where required by law.`]},{id:"records",title:"5. Records and Audit",content:["Administrator actions are logged in Platform audit records as described in the Platform Activity Records Policy.","Audit records may be used for compliance, security, fraud prevention, and legal defence."]},{id:"contact",title:"6. Contact",content:[`Administrator action inquiries: ${e.email}.`]}]},_={id:"corrective-work",title:"Corrective Work Policy",subtitle:"How Providers return to complete remedial work after a dispute.",effectiveDate:v,version:i.correctiveWork,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes what happens when a Provider is instructed to return to a Job site to complete corrective or remedial work on the EloFix Platform, operated by ${e.legalName}.`]},{id:"triggers",title:"2. When Corrective Work Applies",content:["Corrective work may be triggered when a Customer requests a Provider return to fix during a dispute, or when an EloFix administrator resolves a dispute with a Return Provider outcome.","This policy does not apply to new Jobs or scope changes agreed outside of dispute resolution."]},{id:"job-reopening",title:"3. Job Reopening",content:["When corrective work is ordered, the Job status changes back to In Progress.","The dispute is closed or cleared from the active Job status, and the completion timeline restarts.","Previous completion timestamps and confirmation deadlines are reset."]},{id:"payment-protection",title:"4. Payment Protection",content:["Any remaining staged payment tranche (final provider payment) remains paused and does not become payable until the Customer verifies the remedial work.","No additional labor charge applies for corrective work ordered through dispute resolution unless separately agreed through Platform flows."]},{id:"re-verification",title:"5. Re-Verification by Customer",content:["After completing remedial work, the Provider must mark the Job as complete again.","The Customer receives a new notification and a fresh 7-day verification window under the Job Completion Verification Policy.","The Customer may accept, dispute again, or allow automatic acceptance after 7 days."]},{id:"provider-obligations",title:"6. Provider Obligations",content:["Providers must complete corrective work professionally and within a reasonable timeframe.","Failure to complete corrective work may result in further dispute action, refund, account restrictions, or trust score penalties."]},{id:"contact",title:"7. Contact",content:[`Corrective work questions: ${e.email}.`]}]},u="August 18, 2026",U={id:"portfolio-content-rights",title:"Portfolio Content Rights",subtitle:"How completion evidence, reviews, and ratings may be displayed on EloFix.",effectiveDate:u,version:i.portfolioContentRights,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the rights granted to ${e.legalName}, operating the EloFix Platform, to display Customer-submitted completion content on Provider portfolios and Platform marketing.`,n]},{id:"customer-submissions",title:"2. Customer Submissions",content:["When a Customer accepts completed work, they may upload photographs, videos, star ratings, and written reviews.","Upon submission, the Customer grants EloFix a non-exclusive, royalty-free, worldwide licence to host, display, reproduce, and distribute such content on the Platform.","This licence includes display on Provider portfolio pages, Provider profile pages, search results, and Platform marketing materials.","The Customer retains ownership of their content. The licence is limited to operating and promoting the Platform."]},{id:"provider-portfolios",title:"3. Provider Portfolios",content:["Provider portfolios may display verified completed projects including photographs, videos, ratings, reviews, and completion dates.","Where a Job was automatically accepted after the 7-day verification window without a Customer review, the portfolio entry may be displayed without a public star rating and may be flagged as auto-completed.","Providers may also upload curated portfolio images and work posts subject to Community Standards."]},{id:"removal",title:"4. Content Removal",content:["EloFix may remove or restrict content that violates the Community Standards, infringes third-party rights, or is required to be removed by law.",`Customers may request review of portfolio content through ${e.email}. EloFix will assess requests in accordance with POPIA and this policy.`]},{id:"survival",title:"5. Licence Duration",content:["The licence granted upon submission survives account deactivation for historical Job records associated with completed work, to the extent necessary to maintain accurate marketplace records and Provider portfolios."]},{id:"contact",title:"6. Contact",content:[`Portfolio content questions: ${e.email}.`]}]},B={id:"provider-verification",title:"Provider Verification Policy",subtitle:"Identity and business verification requirements for EloFix Providers.",effectiveDate:u,version:i.providerVerification,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the verification requirements for Providers on the EloFix Platform, operated by ${e.legalName}, before they may accept paid Jobs and receive settlement of eligible funds where supported.`,n]},{id:"required-documents",title:"2. Required Documents",content:["Providers may be required to submit the following documents and information:","South African identity document (ID book or smart card).","Business registration documents (company registration certificate or equivalent for registered businesses).","Proof of address (not older than 3 months where applicable).","Banking information for a settlement destination profile. Bank details saved is not the same as bank account verification pending, gateway payout destination verified, settlement supported, or settlement completed.","Optional: proof of skill, trade certifications, or professional qualifications.","EloFix may request additional documentation at any time."]},{id:"verification-process",title:"3. Verification Process",content:["Providers upload documents through the Platform. Documents are reviewed by EloFix administrators.","Each document may be individually approved or rejected with feedback.","Provider account approval requires all mandatory documents to be approved, profile completion, and clearance of fraud review.","Banking details may remain pending verification. Adding banking details does not authorize EloFix to debit the account and does not guarantee that automatic bank settlement is available."]},{id:"denial-revocation",title:"4. Denial and Revocation",content:["Verification may be denied if documents are incomplete, invalid, fraudulent, or do not match account information.","Verification may be revoked if documents expire, fraud is detected, duplicate identities are found, or policy violations occur.","Providers with fraud review status PENDING_REVIEW or REJECTED cannot be approved until cleared by administrators."]},{id:"duplicate-checks",title:"5. Duplicate Identity Checks",content:["EloFix checks for duplicate South African ID numbers, company registration numbers, bank accounts, and document file hashes across the Platform.","Duplicate matches trigger fraud alerts and may block verification approval. See the Fraud Prevention Policy."]},{id:"popia",title:"6. POPIA and Special Personal Information",content:["Identity documents and banking details constitute special personal information under POPIA Section 26.","EloFix processes this information based on contractual necessity for Provider onboarding and legitimate interest for fraud prevention and settlement-destination integrity.","Sensitive fields are encrypted or hashed where appropriate. See the Privacy Policy."]},{id:"contact",title:"7. Contact",content:[`Verification questions: ${e.email}.`]}]},H={id:"fraud-prevention",title:"Fraud Prevention Policy",subtitle:"How EloFix detects and responds to fraudulent activity.",effectiveDate:u,version:i.fraudPrevention,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes how ${e.legalName}, operating the EloFix Platform, monitors for and responds to fraudulent activity on the Platform.`,n]},{id:"monitoring",title:"2. What EloFix Monitors",content:["EloFix may monitor for indicators of fraud including:","Duplicate accounts linked to the same phone number, email patterns, or identity documents.","Duplicate South African ID numbers, company registration numbers, or bank accounts across accounts.","Duplicate or reused verification document files.","Suspicious devices sharing fingerprints across multiple accounts.","Unusual payment behaviour, chargebacks, and refund patterns.","Suspicious login activity and session anomalies."]},{id:"device-rules",title:"3. Device-Based Rules",content:["More than 5 Provider accounts on the same device may trigger a suspicious device alert.","More than 10 Customer accounts on the same device may trigger a suspicious device alert.","Two or more Provider accounts sharing a device fingerprint may trigger investigation."]},{id:"actions",title:"4. EloFix Actions",content:["In response to suspected fraud, EloFix may:","Suspend or restrict accounts.","Request additional verification documents.","Reject new registrations.","Block Provider approval pending fraud review.","Revoke verification status.","Withhold or reverse settlement instructions or recorded payouts where supported by Platform accounting and the payment service provider.","Report activity to law enforcement where appropriate."]},{id:"trust-impact",title:"5. Trust Score Impact",content:["Fraud alerts and duplicate registrations may reduce Provider trust scores. See the Provider Reputation Policy for penalty amounts.","Fake or duplicate documentation may result in significant trust score penalties and permanent account removal."]},{id:"contact",title:"6. Contact",content:[`Fraud concerns: ${e.email}.`]}]},G={id:"device-security",title:"Device Security Policy",subtitle:"How EloFix collects and uses device information for security and fraud prevention.",effectiveDate:u,version:i.deviceSecurity,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the device and session information collected by ${e.legalName}, operating the EloFix Platform, for security, fraud prevention, and account protection, in alignment with POPIA.`,"This policy supplements the Privacy Policy."]},{id:"data-collected",title:"2. Information Collected",content:["EloFix may collect the following device and session information when you log in or register:","Device fingerprint (visitor identifier generated by FingerprintJS or similar technology).","Browser fingerprint and user agent string.","IP address.","Operating system and browser type.","Approximate geographic location derived from IP (country and city).","Session activity and login timestamps.","Login count per device-user link."]},{id:"purpose",title:"3. Purpose of Collection",content:["Device information is collected for:","Account security and unauthorized access detection.","Fraud prevention and duplicate account identification.","Investigation of suspicious activity.","Platform integrity and abuse prevention."]},{id:"popia-basis",title:"4. POPIA Lawful Basis",content:["EloFix processes device information based on legitimate interest in protecting the Platform and its users, balanced against your privacy rights.","Device data is not sold to third parties.","Device session records are retained for approximately 24 months, subject to the Privacy Policy retention schedule."]},{id:"collection-timing",title:"5. When Collection Occurs",content:["Device fingerprinting is initiated after successful login or registration through the Platform.","Collection is non-blocking and does not prevent account access if fingerprinting fails."]},{id:"your-rights",title:"6. Your Rights",content:[`You may contact ${e.email} to exercise POPIA rights regarding device data, including access and objection where applicable.`]},{id:"contact",title:"7. Contact",content:[`Device security questions: ${e.email}.`]}]},z={id:"provider-reputation",title:"Provider Reputation Policy",subtitle:"How EloFix calculates and uses Provider trust scores.",effectiveDate:u,version:i.providerReputation,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the EloFix Provider trust score system operated by ${e.legalName} and how it may affect Provider visibility and ranking on the Platform.`,"Trust scores are an internal reputation metric. They are not a guarantee of service quality."]},{id:"score-range",title:"2. Score Range and Levels",content:["Provider trust scores range from 0 to 100. New Providers start at 100.","Trust levels include: Elite Provider (90–100), Trusted Provider (75–89), Monitor (60–74), Restricted (40–59), and High Risk (0–39).","Trust levels may affect Provider visibility, search ranking, and eligibility for certain Platform features at EloFix's discretion."]},{id:"factors",title:"3. Factors Considered",content:["Trust scores may consider:","Verification status and approved identity documents.","Customer reviews and star ratings.","Job completion rate.","Disputes opened and dispute outcomes.","Refunds (partial and full).","Customer complaints and fraud alerts.","Months without disputes or fraud alerts."]},{id:"adjustments",title:"4. Score Adjustments",content:["Indicative adjustments include:","Job completed: +2. Five-star review included in completion: +3 total.","Verified ID, company registration, or bank account: +10 each (once).","Month without disputes or fraud alerts: +5 (periodic).","Partial refund: −10. Full refund: −25.","Dispute lost: −15. Fraud alert: −20.","Duplicate registration: −25. Fake documentation: −50. Suspicious login: −10.","Automatic acceptance after 7-day window applies a neutral trust adjustment.","EloFix may adjust scoring methodology with notice through policy updates."]},{id:"not-a-guarantee",title:"5. Not a Guarantee",content:["Trust scores and levels are provided for marketplace transparency and safety. They do not constitute a warranty of Provider skill, reliability, or suitability.","Customers should review Provider profiles, reviews, and portfolios when selecting a Provider."]},{id:"contact",title:"6. Contact",content:[`Trust score questions: ${e.email}.`]}]},Q={id:"platform-activity-records",title:"Platform Activity Records Policy",subtitle:"How EloFix stores activity records for security, compliance, and legal defence.",effectiveDate:u,version:i.platformActivityRecords,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the Platform activity records maintained by ${e.legalName}, operating the EloFix Platform.`,"This policy supplements the Privacy Policy."]},{id:"records-stored",title:"2. Records Stored",content:["EloFix may store the following categories of activity records:","Login and authentication records.","Payment and payment-schedule transaction records.","Provider verification and document review records.","Fraud investigation and alert records.","Dispute submissions, messages, and resolution actions.","Administrator actions on accounts, payments, disputes, refunds, and settlement records.","Job status changes, completion events, and automatic acceptance events.","Review and rating submissions.","Device session records."]},{id:"purposes",title:"3. Purposes",content:["Activity records are maintained for:","Platform security and fraud prevention.","Regulatory and legal compliance.","Dispute investigation and resolution.","Legal defence and evidence preservation.","Service improvement and audit."]},{id:"access",title:"4. Access and Confidentiality",content:["Access to activity records is limited to authorised EloFix administrators and subprocessors with a legitimate need.","Records are protected by access controls and security measures described in the Privacy Policy."]},{id:"retention",title:"5. Retention",content:["Activity records are retained in accordance with the retention schedule in the Privacy Policy.","Audit logs are typically retained for 5 years. Payment records for 7 years. Device sessions for 24 months."]},{id:"contact",title:"6. Contact",content:[`Records inquiries: ${e.email}.`]}]},T="August 18, 2026",K={id:"supplier-agreement",title:"Supplier Agreement",subtitle:"Terms for businesses supplying materials through the EloFix marketplace.",effectiveDate:T,version:i.supplierAgreement,sections:[{id:"relationship",title:"1. Independent Supplier Relationship",content:[`This Supplier Agreement supplements the EloFix Terms of Service for businesses that register as Suppliers on the EloFix Platform, operated by ${e.legalName}.`,n,`You are an independent business and not an employee, agent, joint venturer, or partner of ${e.legalName}.`,"You are solely responsible for the products you list, sell, and deliver through the Platform."]},{id:"onboarding",title:"2. Onboarding and Account Setup",content:["Suppliers must complete business profile setup, branch configuration, and accept the Supplier Participation Policy before listing products.","Branch Users (staff) act on behalf of the Supplier and must comply with this Agreement and the Supplier Participation Policy.","You represent that all business information submitted is accurate and current."]},{id:"commission",title:"3. Commission and Payments",content:["EloFix charges a platform commission of 7% on the materials subtotal for orders fulfilled through the Platform.","Your earning is the materials subtotal minus the platform commission and is recorded after Customer payment confirmation through the applicable payment service provider.","Where supported by EloFix's payment service provider and applicable settlement configuration, eligible Supplier or branch funds may be settled to a nominated verified bank account. EloFix does not promise automatic bank settlement where marketplace settlement is not supported. Banking details must be accurate and may require verification; saving bank details is not the same as verified settlement or completed settlement.","Material payments are not subject to job-completion staged payment holds.","EloFix may deduct refunds, chargebacks, and adjustments from amounts recorded as payable to you through supported Platform accounting and repayment mechanisms."]},{id:"fulfilment",title:"4. Order Fulfilment and Delivery",content:["You must accept, prepare, and fulfil material orders in accordance with the Supplier Participation Policy and displayed fulfilment timelines.","You are responsible for delivery obligations, tracking, and customer communication regarding order status.","Delivery fees may be processed as separate payment intents."]},{id:"refunds-chargebacks",title:"5. Refunds and Chargebacks",content:["You are responsible for refund and chargeback costs associated with your orders, including commission reversals where applicable, through supported Platform accounting and repayment mechanisms.","Refund eligibility depends on fulfilment stage as described in the Refund, Returns & Cancellation Policy."]},{id:"data",title:"6. Data Handling",content:["You must handle Customer personal information received through orders in compliance with POPIA. You may only use such data for order fulfilment.","See the Data Processing Policy for EloFix's role as responsible party."]},{id:"indemnification",title:"7. Indemnification and Liability",content:[`You indemnify ${e.legalName} for claims arising from products you supply, including defective goods, incorrect items, delivery failures, and regulatory non-compliance.`,"You are solely responsible for product quality, safety, labelling, and compliance with South African consumer protection law."]},{id:"termination",title:"8. Suspension and Termination",content:["EloFix may suspend or remove Supplier access for policy violations, poor fulfilment performance, fraud, or legal risk.","You may deactivate your account subject to completion of outstanding orders and payment obligations."]},{id:"updates",title:"9. Updates",content:["We may update this Supplier Agreement from time to time. Material changes may require renewed acceptance."]}]},X={id:"supplier-participation",title:"Supplier Participation Policy",subtitle:"Operational standards for listing and fulfilling products on EloFix.",effectiveDate:T,version:i.supplierParticipation,sections:[{id:"overview",title:"1. Overview",content:[`This policy describes the responsibilities of Suppliers participating in the EloFix materials marketplace operated by ${e.legalName}.`,n]},{id:"pricing-accuracy",title:"2. Pricing Accuracy",content:["Suppliers must ensure that listed prices are accurate, current, and inclusive of applicable taxes where required by law.","Price changes must be updated on the Platform before they apply to new orders."]},{id:"stock-accuracy",title:"3. Stock and Inventory Accuracy",content:["Suppliers must maintain accurate stock levels and inventory data for each branch.","Accepting orders for out-of-stock items is prohibited. Repeated stock inaccuracies may result in listing restrictions."]},{id:"product-descriptions",title:"4. Product Descriptions",content:["Product descriptions, specifications, images, and categories must be accurate and not misleading.","Suppliers are responsible for ensuring products comply with applicable safety standards and labelling requirements in South Africa."]},{id:"delivery",title:"5. Delivery Obligations",content:["Suppliers must fulfil delivery obligations according to configured delivery settings and order acceptance timelines.","Delivery issues, delays, and tracking updates must be communicated through the Platform.","Suppliers must cooperate with delivery rating and feedback processes."]},{id:"marketing",title:"6. Marketing Permissions",content:["By listing products on EloFix, Suppliers grant EloFix a non-exclusive licence to display product images, names, descriptions, and pricing in Platform search, marketing, and promotional materials."]},{id:"listing-removal",title:"7. Listing Removal",content:["EloFix may remove or restrict product listings that violate this policy, the Community Standards, applicable law, or that receive repeated customer complaints.","EloFix may remove Supplier access entirely for serious or repeated violations."]},{id:"contact",title:"8. Contact",content:[`Supplier participation questions: ${e.email}.`]}]},g="August 18, 2026",Z={id:"data-processing",title:"Data Processing Policy",subtitle:"How EloFix processes personal information as operator and uses subprocessors.",effectiveDate:g,version:i.dataProcessing,sections:[{id:"overview",title:"1. Overview",content:[`This Data Processing Policy describes how ${e.legalName}, operating the EloFix Platform ("EloFix"), processes personal information in its role as responsible party under POPIA.`,n,"This policy supplements the Privacy Policy."]},{id:"roles",title:"2. Roles",content:["EloFix acts as the responsible party for personal information collected through the Platform. Whether EloFix or a third party also acts as an operator for specific processing activities depends on the contractual arrangement and requires appropriate legal review.","Payment service providers, hosting providers, and device intelligence services process payment or technical data according to their roles and EloFix's instructions where applicable.","Providers and Suppliers who receive Customer data through Jobs or orders must process that data in compliance with POPIA for their own purposes."]},{id:"subprocessors",title:"3. Subprocessors",content:["EloFix uses the following categories of subprocessors:","Third-party payment service providers that process Customer payments, refunds, and related payment events.","Cloud hosting and database infrastructure providers.","Device intelligence: FingerprintJS or equivalent fingerprinting technology.","Email and notification delivery services.","Maps and location services where applicable.","Subprocessors are engaged under contractual terms requiring appropriate security and confidentiality."]},{id:"security",title:"4. Security Measures",content:["EloFix implements administrative, technical, and organizational measures including:","Encryption of sensitive personal information at rest and in transit.","Role-based access controls for administrator functions.","Audit logging of sensitive operations.","Hashing of identity and bank account numbers for duplicate detection.","Regular security reviews of Platform infrastructure.","EloFix does not store CVV. Full payment-card details, where collected at all, are handled according to the applicable payment service provider's systems and tokenization practices."]},{id:"breach",title:"5. Data Breach Notification",content:["In the event of a personal information breach, EloFix will assess the breach and notify the Information Regulator and affected data subjects as required by POPIA Section 22.",`Breach reports may be sent to ${e.email}.`]},{id:"instructions",title:"6. Processing Instructions",content:["EloFix processes personal information only for the purposes described in the Privacy Policy and incorporated Platform policies.","EloFix does not sell personal information to third parties."]},{id:"contact",title:"7. Contact",content:[`Data processing inquiries: ${e.email} (Information Officer).`]}]},ee={id:"community-standards",title:"Community Standards",subtitle:"Expected behaviour and content standards for all EloFix users.",effectiveDate:g,version:i.communityStandards,sections:[{id:"overview",title:"1. Overview",content:[`These Community Standards describe expected behaviour for all users of the EloFix Platform, operated by ${e.legalName}.`,n,"Violations may result in content removal, account restrictions, or permanent removal from the Platform."]},{id:"respect",title:"2. Respect and Safety",content:["Treat other users with respect. Harassment, threats, hate speech, discrimination, and abusive language are prohibited.","Do not engage in violence, intimidation, or unsafe behaviour on or off the Platform in connection with Jobs or orders."]},{id:"honesty",title:"3. Honesty and Accuracy",content:["Provide accurate information in profiles, listings, quotes, and communications.","Do not misrepresent your identity, qualifications, business registration, or product specifications.","Do not submit fraudulent verification documents or fake completion evidence."]},{id:"payments",title:"4. Platform Payments",content:["Use Platform payment flows for Jobs and orders arranged through EloFix.","Do not circumvent Platform fees by soliciting off-platform payments for Platform-originated work."]},{id:"content",title:"5. Content Standards",content:["Do not upload illegal, obscene, defamatory, or infringing content.","Completion photos, reviews, and portfolio images must relate to actual completed work.","Do not manipulate reviews, post fake ratings, or retaliate against users for honest feedback."]},{id:"prohibited",title:"6. Prohibited Activity",content:["Prohibited activity includes: fraud, identity theft, money laundering, spam, malware distribution, scraping, unauthorized access, and interference with Platform operations.","Creating duplicate accounts to evade restrictions is prohibited. See the Fraud Prevention Policy."]},{id:"enforcement",title:"7. Enforcement",content:["EloFix may warn, restrict, suspend, or permanently remove accounts for Community Standards violations.","Serious violations may be reported to law enforcement.","See the Admin Review and Investigation Policy for administrator enforcement authority."]},{id:"contact",title:"8. Report Violations",content:[`Report Community Standards violations to ${e.email}.`]}]},te={id:"cookie-policy",title:"Cookie Policy",subtitle:"How EloFix uses cookies and similar technologies.",effectiveDate:g,version:i.cookiePolicy,sections:[{id:"overview",title:"1. Overview",content:[`This Cookie Policy explains how ${e.legalName}, operating the EloFix Platform ("EloFix"), uses cookies and similar technologies on the Platform.`,"This policy supplements the Privacy Policy."]},{id:"what-are-cookies",title:"2. What Are Cookies",content:["Cookies are small text files stored on your device when you visit a website. Similar technologies include local storage, session tokens, and pixel tags."]},{id:"cookies-we-use",title:"3. Cookies We Use",content:["Essential cookies: required for authentication, session management, and security. These cannot be disabled without affecting Platform functionality.","Preference cookies: remember your settings and choices.","Analytics cookies: help us understand how the Platform is used and improve performance.","Security cookies: support fraud prevention and device recognition in conjunction with the Device Security Policy."]},{id:"third-party",title:"4. Third-Party Cookies",content:["Payment partners, maps services, and analytics providers may set their own cookies when you interact with their features on the Platform.","We do not control third-party cookies. Refer to those providers' privacy policies for details."]},{id:"managing",title:"5. Managing Cookies",content:["You can manage cookies through your browser settings. Disabling essential cookies may prevent you from logging in or using core Platform features.",`To exercise broader privacy rights, contact ${e.email}.`]},{id:"contact",title:"6. Contact",content:[`Cookie questions: ${e.email}.`]}]},oe="August 18, 2026",ie={id:"delivery-policy",title:"Delivery & Collection Policy",subtitle:"How collection, store delivery, and courier delivery work for EloFix material orders and courier jobs.",effectiveDate:oe,version:i.deliveryPolicy,sections:[{id:"overview",title:"1. Overview",content:[n,"This Delivery & Collection Policy describes how materials and courier jobs are collected or delivered when arranged through the EloFix Platform.",`${e.brandName} is a marketplace. Independent suppliers fulfil material orders. Independent delivery providers (couriers) may transport goods or complete standalone delivery and moving jobs. ${e.legalName} does not itself operate a courier fleet or warehouse.`,"Payment processing for materials and delivery fees is handled through applicable third-party payment service provider(s). Delivery fees, where charged, are typically processed as a separate payment from the materials payment."]},{id:"scope",title:"2. Scope",content:["This policy covers: (a) customer pickup / branch collection of material orders; (b) supplier or store delivery of material orders; (c) hired delivery-provider / courier delivery of material orders; and (d) standalone delivery or moving jobs requested through the Platform.","Service Jobs that do not involve material fulfilment or courier transport are governed by the Terms of Service, Provider Agreement, and related policies.","This policy should be read with the Refund, Returns & Cancellation Policy, Supplier Agreement, Supplier Participation Policy, and Provider Agreement."]},{id:"collection",title:"3. Customer Pickup / Branch Collection",content:["Where the Platform offers collection, a Customer may choose to collect a material order from the fulfilling supplier branch.","Collection from the branch does not attract a Platform delivery fee. The Customer is responsible for collecting the goods at the branch during the times and conditions communicated on the order.","The supplier prepares the order and marks it ready for collection. The Customer should confirm collection through the Platform when the goods have been collected.","Risk in the goods transfers according to the supplier's fulfilment and applicable law. Customers should inspect goods at collection and report issues promptly through the Platform."]},{id:"store-delivery",title:"4. Supplier / Store Delivery",content:["Some supplier branches offer store delivery. This option is available only where the branch has enabled delivery on the Platform.","The branch quotes a delivery fee after the Customer requests store delivery. The quoted fee is not automatically calculated at checkout and is not a guaranteed tariff.","After the Customer accepts the quoted delivery fee, the delivery fee is paid as a separate payment through the applicable payment service provider.","The supplier is responsible for fulfilling store delivery, including packing, transport, and customer communication for that mode, subject to this policy and the Supplier Agreement.","Where the Platform enables live location sharing for store delivery, that tracking is supplier-led while the order is out for delivery."]},{id:"courier-delivery",title:"5. Delivery Provider / Courier Delivery",content:["A Customer may request a delivery provider (courier) to collect materials from a supplier and deliver them to a destination address, where that option is offered on the order.","The selected delivery provider quotes a delivery fee. Displayed profile rates or estimated times, if shown, are indicative only and are not the charged amount unless the Customer accepts a quote.","After the Customer accepts the quote, the delivery fee is paid as a separate payment through the applicable payment service provider.","The delivery provider is an independent service provider, not an employee of EloFix or of LITI Holdings (Pty) Ltd. The courier is responsible for collection, transport, and delivery of the assigned order, subject to the Provider Agreement and this policy.","Where the Platform enables live location sharing for courier delivery, that tracking is provider-led while the courier is collecting or out for delivery."]},{id:"standalone-jobs",title:"6. Standalone Delivery and Moving Jobs",content:["Customers may request standalone delivery or moving jobs through the Platform, separate from a material order.","These jobs require a collection address and a destination address. The addresses must be distinct.","An independent delivery or moving provider submits a quote. The Customer pays after accepting the quote, according to the payment model shown for that service category.","Standalone courier and moving jobs follow the applicable Job, completion, cancellation, and dispute policies in addition to this policy."]},{id:"fees",title:"7. Delivery Fee Calculation",content:["Branch collection: no Platform delivery fee.","Store delivery: the fulfilling branch quotes the fee. The Customer pays the quoted fee after acceptance.","Courier delivery (materials): the assigned delivery provider quotes the fee. The Customer pays the quoted fee after acceptance.","Standalone delivery or moving jobs: the provider quotes for the job as shown on the Platform.","EloFix does not promise a fixed per-kilometre tariff, a maximum fee, or that a previously quoted fee will remain available if the quote expires or the order changes."]},{id:"addresses",title:"8. Delivery Addresses",content:["Customers must provide accurate collection and/or destination details as required by the selected fulfilment mode, including address, city, and any access instructions requested on the Platform.","For branch collection, the collection point is the supplier branch address shown on the order.","For store or courier delivery, the destination is the Customer delivery address captured for the order.","Incorrect, incomplete, or inaccessible addresses may result in delay, failed delivery, additional quotes, or cancellation according to Platform status rules."]},{id:"timing",title:"9. Estimated Delivery Timing",content:["EloFix does not guarantee delivery dates or times. Any estimated time shown on a provider profile, map, or tracking view is operational information only and is not a contractual service-level agreement.","Live map duration, where displayed, is an approximate driving estimate and may change with traffic, access, weather, load shedding, or the parties' availability.","Suppliers and delivery providers should communicate material delays through the Platform."]},{id:"tracking",title:"10. Order Tracking",content:["Where a tracking session is created for an order, the Customer may follow status updates on the Platform and, where issued, on the public tracking page associated with that order.","Live GPS tracking, where available, typically applies while store delivery is out for delivery (supplier-led) or while a courier is collecting or out for delivery (provider-led).","Tracking may be unavailable for collection orders, before dispatch, after completion, or if a tracking session expires or is not started."]},{id:"confirmation",title:"11. Delivery and Collection Confirmation",content:["Collection: the Customer should confirm collection through the Platform when the supplier has marked the order ready and the goods have been collected.","Store or courier delivery: the supplier or courier marks delivery complete according to Platform fulfilment steps. The Customer may acknowledge receipt through the Platform.","If the Customer has opened a delivery-issue report, confirmation of receipt may be blocked until the issue is handled according to Platform processes.","Customers may be invited to rate the fulfilment after completion."]},{id:"failed-delayed",title:"12. Failed Delivery and Delays",content:["A supplier or courier may mark a delivery as delayed or failed where the Platform supports those fulfilment statuses, for example where the recipient is unavailable, the address cannot be accessed, or an operational issue prevents completion.","Delayed deliveries may continue through later fulfilment steps if the parties resume the delivery.","Failed deliveries should be communicated through the Platform. A replacement attempt, re-quote, collection instead of delivery, or cancellation may follow depending on order status, the parties' agreement, and applicable refund rules.","EloFix does not guarantee a successful delivery attempt or a specific number of re-attempts."]},{id:"damaged-incorrect",title:"13. Damaged or Incorrect Goods",content:["Customers should inspect goods on collection or delivery.","For material orders, the Platform allows a Customer to report delivery issues after fulfilment is marked complete and before the Customer confirms receipt. Reportable issues include missing items, broken or damaged items, wrong items, goods not received, or other problems described on the form.","Reporting an issue notifies the relevant supplier branch so the matter can be investigated. Refunds, replacements, or returns follow the Refund, Returns & Cancellation Policy and the supplier's fulfilment of the order.","EloFix facilitates the report and related Platform records. The supplier remains responsible for the goods they supply. A delivery provider remains responsible for the transport they undertake."]},{id:"cancellation",title:"14. Cancellation",content:["Material-order cancellation by the Customer is generally available while the order is still pending, accepted, being prepared, or ready for collection, and is not available after the order has been dispatched / is out for delivery.","A supplier may cancel an order in accordance with Platform rules except where the order is already cancelled, completed, or failed, subject to refund treatment in the Refund, Returns & Cancellation Policy.","Standalone courier or moving jobs generally cannot be cancelled by the Customer after items have been collected, or while the job is awaiting completion confirmation, as implemented on the Platform.","While a courier Provider is collecting items and labor has been paid, Customer cancellation may result in no labor refund where the Refund, Returns & Cancellation Policy provides for that courier en-route forfeiture. Ordinary service Jobs do not use that automatic R0 rule; they may open an administrator review instead.","Specific eligibility is determined by Platform status at the time of cancellation and the Refund, Returns & Cancellation Policy. This policy does not create additional refund rights."]},{id:"customer-responsibilities",title:"15. Customer Responsibilities",content:["Provide complete and accurate addresses and contact details.","Be available to collect goods or receive delivery, or arrange an authorised recipient.","Pay quoted delivery fees when you accept them, through the Platform payment flow.","Inspect goods and report issues promptly through the Platform.","Do not request delivery to an unlawful or inaccessible location."]},{id:"supplier-responsibilities",title:"16. Supplier Responsibilities",content:["Prepare, pack, and make goods available according to the selected fulfilment mode and the Supplier Participation Policy.","Quote store-delivery fees accurately where store delivery is offered, and fulfil store delivery with reasonable care.","Keep stock, product descriptions, and order status accurate.","Communicate delays, failed delivery, and tracking updates through the Platform.","Cooperate with delivery-issue reports, ratings, and any investigation."]},{id:"provider-responsibilities",title:"17. Delivery-Provider Responsibilities",content:["Quote fairly for the collection and destination shown on the assignment.","Collect, transport, and deliver with reasonable care, and update Platform fulfilment status honestly.","Share live location while collecting or out for delivery where the Platform requires tracking for that assignment.","Report failed or delayed delivery through the Platform.","Comply with the Provider Agreement, Community Standards, and applicable road-traffic and goods-handling law."]},{id:"contact",title:"18. Contact",content:[`Questions about this Delivery & Collection Policy may be sent to ${e.email} with your order or Job reference number.`,`${e.operatorStatement} Country of domicile: ${e.country}.`]}]},re={terms:N,privacy:O,"provider-agreement":W,"refund-policy":$,"job-completion-verification":Y,"escrow-policy":L,"dispute-resolution":M,"admin-investigation":V,"corrective-work":_,"portfolio-content-rights":U,"provider-verification":B,"fraud-prevention":H,"device-security":G,"provider-reputation":z,"supplier-agreement":K,"supplier-participation":X,"data-processing":Z,"community-standards":ee,"cookie-policy":te,"platform-activity-records":Q,"delivery-policy":ie};function ae(a){return re[a]}function ne({documentId:a}){return t.jsx(R,{wide:!0,children:t.jsx(q,{document:ae(a)})})}function r(a){return function(){return t.jsx(ne,{documentId:a})}}const be=r("terms"),we=r("privacy"),Pe=r("provider-agreement"),Ce=r("refund-policy"),xe=r("job-completion-verification"),ke=r("escrow-policy"),Ee=r("dispute-resolution"),Fe=r("admin-investigation"),Te=r("corrective-work"),Ae=r("portfolio-content-rights"),Se=r("provider-verification"),Re=r("fraud-prevention"),De=r("device-security"),Ie=r("provider-reputation"),qe=r("supplier-agreement"),je=r("supplier-participation"),Ne=r("data-processing"),Je=r("community-standards"),Oe=r("cookie-policy"),We=r("platform-activity-records"),$e=r("delivery-policy");export{Fe as AdminInvestigationPage,Je as CommunityStandardsPage,Oe as CookiePolicyPage,Te as CorrectiveWorkPage,Ne as DataProcessingPage,$e as DeliveryPolicyPage,De as DeviceSecurityPage,Ee as DisputeResolutionPage,ke as EscrowPolicyPage,Re as FraudPreventionPage,xe as JobCompletionVerificationPage,We as PlatformActivityRecordsPage,Ae as PortfolioContentRightsPage,we as PrivacyPage,Pe as ProviderAgreementPage,Ie as ProviderReputationPage,Se as ProviderVerificationPage,Ce as RefundPolicyPage,qe as SupplierAgreementPage,je as SupplierParticipationPage,be as TermsPage};
